import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

/** Next SD100 cards: shared reaction/cost paths are tested with real bundled definitions. */
public final class StarterDeck100ContinuationTest {
    static final UUID A=StarterDeck100PokemonTest.A,B=StarterDeck100PokemonTest.B;
    static String id(int n){return StarterDeck100PokemonTest.id(n);}
    static void check(boolean b,String s){StarterDeck100PokemonTest.check(b,s);}
    static ServerMatch game(int n,String...extras){return StarterDeck100PokemonTest.game(n,extras);}
    static void attack(ServerMatch m,int n){StarterDeck100PokemonTest.attack(m,n);}
    static void select(ServerMatch m,int n){StarterDeck100PokemonTest.select(m,n);}
    static CardInstance hand(ServerMatch m,String id){return StarterDeck100PokemonTest.hand(m,id);}
    static void ability(ServerMatch m,UUID p){StarterDeck100PokemonTest.ability(m,p);}
    static void discard(ServerMatch m,String id,int count){var cards=m.privateView(A).deck().stream().filter(c->c.definitionId().equals(id)).limit(count).toList();check(cards.size()==count,"discard fixture insufficient");m.searchOwnDeckToHandByEffect(A,cards.stream().map(CardInstance::instanceId).toList());m.discardHandCardsByEffect(A,A,cards.stream().map(CardInstance::instanceId).toList());}
    public static void main(String[] args){coalCannon();oppressingSandstorm();tripleHeads();bothPoison();selfCounters();direflame();strangeBehavior();toxicPoison();aftermath(false);aftermath(true);hangry();seismicRift();spiralBurst();extremeFreeze();skyReturn();secondPlayerDraw();urn();fogCrystal();peony();System.out.println("StarterDeck100ContinuationTest passed: SD100 printed poison strength, shared limits, reactions, bound Energy choices, whole-hand discard and first-turn timing");}
    static void coalCannon(){var m=game(240);for(int i=0;i<21;i++){var energy=m.privateView(A).deck().stream().filter(c->m.cardDefinition(c.definitionId()).category()==CardCategory.ENERGY).findFirst().orElseThrow();StarterDeck100EnergyTest.attach(m,A,A,energy.definitionId(),m.activePokemonView(A).pokemonId());}int before=m.randomTranscript().size();m.attack(A,"coal-cannon");var flips=m.randomTranscript().subList(before,m.randomTranscript().size()).stream().filter(e->e.operation().startsWith("attack-effect-coin:coal-cannon:")).toList();check(flips.size()==21&&m.lastAttack().finalDamage()==90*flips.stream().filter(e->e.result()==0).count(),"Coal Cannon truncated Energy count or used a separate coin result");}
    static void oppressingSandstorm(){var m=game(196);attack(m,1);check(m.phase()==MatchPhase.PRIZE_SELECTION&&m.pendingChoicePlayer().equals(A),"conditional direct KO did not award prizes");StarterDeck100CombatTest.settleKnockouts(m);check(m.publicView().get(A).prizeCount()==4,"Basic V KO must give2 prizes");}
    static void tripleHeads(){var seen=new HashSet<Boolean>();for(int seed=0;seed<100;seed++){var m=StarterDeck100PokemonTest.gameSeed(207,1,seed);attack(m,0);int damage=m.lastAttack().finalDamage();check(damage>=0&&damage<=180&&damage%60==0,"Triple Heads wrong damage");boolean protectedNow=damage==180;StarterDeck100EnergyTest.attach(m,B,B,"sd100_cn_grass_energy",m.activePokemonView(B).pokemonId());StarterDeck100EnergyTest.attach(m,B,B,"sd100_cn_grass_energy",m.activePokemonView(B).pokemonId());m.attack(B,"leaf-drain");check(m.lastAttack().finalDamage()==(protectedNow?0:100),"Triple Heads protection used a different coin result");seen.add(protectedNow);if(seen.size()==2)break;}check(seen.size()==2,"coin fixture did not cover full/partial heads");}
    static void bothPoison(){var m=game(252);attack(m,0);check(m.activePokemonView(A).damage()==10&&m.activePokemonView(B).damage()==10&&m.activePokemonView(A).conditions().contains(SpecialCondition.POISONED),"both Actives must take Poison during Checkup");}
    static void selfCounters(){var m=game(253);attack(m,1);check(m.activePokemonView(A).damage()==30&&m.lastAttack().selfDamage()==0,"Pain Explosion used recoil instead of counters");}
    static void direflame(){var m=game(254,id(422));var alternate=hand(m,id(422));m.playBasicPokemonToBench(A,alternate.instanceId());discard(m,"sd100_cn_darkness_energy",2);UUID active=m.activePokemonView(A).pokemonId();ability(m,active);select(m,1);check(m.activePokemonView(A).attachedEnergyIds().size()==1,"Direflame Wings did not attach to source");TopDeckLookTest.rejects(()->ability(m,alternate.instanceId()));m.endTurn(A);m.endTurn(B);ability(m,alternate.instanceId());select(m,1);check(StarterDeck100PokemonTest.view(m,A,alternate.instanceId()).attachedEnergyIds().size()==1,"Direflame shared limit did not reset next turn");}
    static void strangeBehavior(){var results=new HashSet<Integer>();for(int seed=0;seed<100;seed++){var m=StarterDeck100PokemonTest.gameSeed(257,1,seed);UUID source=m.activePokemonView(A).pokemonId(),target=m.benchPokemonView(A).getFirst().pokemonId();m.placeDamageCountersByEffect(A,A,target,1);ability(m,source);StarterDeck100PokemonTest.choosePokemon(m,target);int damage=StarterDeck100PokemonTest.view(m,A,target).damage();check(damage==0||damage==40,"coin did not heal90 or place3 on chosen Pokemon");results.add(damage);if(results.size()==2)break;}check(results.size()==2,"missing healing coin branch");}
    static void toxicPoison(){var m=game(259);attack(m,0);check(m.activePokemonView(B).damage()==130&&m.activePokemonView(B).conditions().contains(SpecialCondition.POISONED),"Max Toxify must be10 damage then120 Checkup");m.applySpecialConditionByEffect(B,B,SpecialCondition.POISONED);m.endTurn(B);check(m.activePokemonView(B).damage()==140,"new ordinary Poison did not replace twelve-counter Poison");}
    static void aftermath(boolean counters){var m=game(260);UUID source=m.activePokemonView(A).pokemonId();m.placeDamageCountersByEffect(A,A,source,m.activePokemonView(A).hitPoints()/10-1);m.endTurn(A);if(counters)m.placeDamageCountersByEffect(B,A,source,1);else{StarterDeck100EnergyTest.attach(m,B,B,"sd100_cn_grass_energy",m.activePokemonView(B).pokemonId());StarterDeck100EnergyTest.attach(m,B,B,"sd100_cn_grass_energy",m.activePokemonView(B).pokemonId());m.attack(B,"leaf-drain");StarterDeck100EnergyTest.drain(m);}check(m.activePokemonView(B).damage()==(counters?0:60),"Aftermath lethal damage/counter distinction");}
    static void hangry(){for(boolean empty:List.of(false,true)){var m=game(289);StarterDeck100PokemonTest.charge(m,1);if(empty)StarterDeck100PokemonTest.trim(m,0);m.attack(A,"hangry-tackle");check(m.lastAttack().finalDamage()==(empty?110:20),"Hangry Tackle empty hand condition");}}
    static void seismicRift(){var m=game(298);attack(m,1);check(m.activePokemonView(A).damage()==30&&m.benchPokemonView(A).getFirst().damage()==30,"Seismic Rift did not damage own entire field");}
    static void spiralBurst(){for(int branch:List.of(0,1)){var m=game(315);StarterDeck100PokemonTest.charge(m,1);String selected=branch==0?"sd100_cn_fire_energy":"sd100_cn_lightning_energy";StarterDeck100EnergyTest.attach(m,A,A,selected,m.activePokemonView(A).pokemonId());m.attack(A,"spiral-burst");var choice=m.effectChoicePrompt(A);m.chooseEffectOption(A,choice.resolutionId(),choice.step(),branch);var p=m.effectCardPrompt(A);check(p.candidates().size()==2&&p.candidates().stream().allMatch(c->c.definitionId().equals(selected)),"Spiral Burst mixed Energy types");select(m,2);check(m.lastAttack().finalDamage()==180&&m.activePokemonView(A).attachedEnergyIds().size()==1,"Spiral Burst actual discard count");}}
    static void extremeFreeze(){var m=game(320);StarterDeck100PokemonTest.charge(m,0);StarterDeck100EnergyTest.attach(m,A,A,"sd100_cn_water_energy",m.benchPokemonView(A).getFirst().pokemonId());m.attack(A,"extreme-freeze");var p=m.effectCardPrompt(A);check(p.candidates().size()==3&&p.candidates().stream().allMatch(c->c.definitionId().equals("sd100_cn_water_energy")),"Extreme Freeze did not filter Water on entire field");select(m,3);check(m.lastAttack().finalDamage()==180,"Extreme Freeze counted units/base incorrectly");}
    static void skyReturn(){var m=game(348);UUID source=m.activePokemonView(A).pokemonId(),physical=PokemonIdentityTestSupport.physical(m,A,source);StarterDeck100PokemonTest.charge(m,1);var attached=List.copyOf(m.activePokemonView(A).attachedEnergyIds());m.attack(A,"sky-return");check(m.privateView(A).hand().stream().anyMatch(c->c.instanceId().equals(physical))&&m.privateView(A).hand().stream().map(CardInstance::instanceId).toList().containsAll(attached),"Sky Return lost source or attached cards");check(m.phase()==MatchPhase.CHOOSE_REPLACEMENT,"Sky Return did not request replacement");m.chooseReplacement(A,m.benchPokemonView(A).getFirst().pokemonId());check(m.currentPlayer().equals(B),"Sky Return did not end turn");}
    static void secondPlayerDraw(){var m=new ServerMatch(A,B,StarterDeck100PokemonTest.deck(A,1),StarterDeck100PokemonTest.deck(B,353),StarterDeck100CombatTest.RULE,StarterDeck100CombatTest.CARDS,StarterDeck100CombatTest.COMBAT,new ServerRandom(17));OpeningTestSupport.complete(m,A,B,0);m.endTurn(A);StarterDeck100EnergyTest.attach(m,B,B,"sd100_cn_grass_energy",m.activePokemonView(B).pokemonId());for(int expected:List.of(4,1)){int before=m.privateView(B).hand().size();m.attack(B,"tailwind-draw");check(m.privateView(B).hand().size()==before+expected,"Tailwind Draw first second-player turn bonus incorrect");m.endTurn(A);}}
    static void urn(){var m=StarterDeck100CommonTest.game(369,0,id(412),id(414));discard(m,id(412),2);discard(m,id(414),1);StarterDeck100CommonTest.play(m,369);var p=m.effectCardPrompt(A);check(p.candidates().size()==2&&p.candidates().stream().allMatch(c->c.definitionId().equals(id(412))),"Urn recovered another Special Energy");select(m,2);check(m.privateView(A).discard().stream().noneMatch(c->c.definitionId().equals(id(412))),"Urn did not return cards to deck");}
    static void fogCrystal(){var m=StarterDeck100CommonTest.game(371,0,id(171),id(166),"sd100_cn_psychic_energy");StarterDeck100CommonTest.play(m,371);var p=m.effectCardPrompt(A);check(p.candidates().stream().anyMatch(c->c.definitionId().equals(id(171)))&&p.candidates().stream().anyMatch(c->c.definitionId().equals("sd100_cn_psychic_energy"))&&p.candidates().stream().noneMatch(c->c.definitionId().equals(id(166))),"Fog Crystal one mixed Basic Psychic/Energy choice");select(m,1);}
    static void peony(){for(boolean empty:List.of(false,true)){var m=StarterDeck100CommonTest.game(404,0,id(373));if(empty){var card=StarterDeck100CombatTest.hand(m,id(404));m.discardHandCardsByEffect(A,A,m.privateView(A).hand().stream().filter(c->!c.equals(card)).map(CardInstance::instanceId).toList());}var before=List.copyOf(m.privateView(A).hand());StarterDeck100CommonTest.play(m,404);check(m.privateView(A).hand().isEmpty(),"Peony must discard all other hand cards");select(m,2);check(m.privateView(A).hand().size()==2&&m.privateView(A).hand().stream().allMatch(c->m.cardDefinition(c.definitionId()).category()==CardCategory.TRAINER)&&m.privateView(A).discard().containsAll(before),"Peony failed discard/search ordering");}}
}
